 public Yaf_Route_Regex::__construct
 stringmatch
 arrayroute
 arraynullmap&null;
 arraynullverify&null;
 stringnullreverse&null;


 Constrói uma rota Yaf_Route_Regex, que roteia um URI de
 requisição correspondente a uma expressão regular para um módulo, controlador e ação.

  &reftitle.examples;

   Yaf_Route_Regex via Yaf_Router::addRoute


<?php

/**
 * Adiciona uma rota regex à pilha de rotas de Yaf_Router
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute(
    "name",
    new Yaf_Route_Regex(
        "#^/product/([^/]+)/([^/]+)#", // corresponde a um URI iniciado por "/product"
        array(
            'controller' => "product", // roteia para o controlador product
        ),
        array(
            1 => "name", // $request->getParam("name") contém a primeira captura
            2 => "id",   // e $request->getParam("id") a segunda
        )
    )
);
?>




   Yaf_Route_Regex usando uma captura como nome do controlador


<?php

/**
 * Usa uma captura como nome do controlador
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute(
    "name",
    new Yaf_Route_Regex(
        "#^/product/([^/]+)/([^/]+)#i", // corresponde a um URI iniciado por "/product"
        array(
            'controller' => ":name", // a captura "name" (consulte map) torna-se o controlador
        ),
        array(
            1 => "name", // $request->getParam("name") contém a primeira captura
            2 => "id",   // e $request->getParam("id") a segunda
        )
    )
);
?>




   Yaf_Route_Regex usando um grupo de captura nomeado


<?php

/**
 * Usa um grupo de captura nomeado como nome do controlador
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute(
    "name",
    new Yaf_Route_Regex(
        "#^/product/(?<name>[^/]+)/([^/]+)#i", // corresponde a um URI iniciado por "/product"
        array(
            'controller' => ":name", // a captura "name" torna-se o controlador
        ),
        array(
            2 => "id", // o grupo 1 é nomeado, apenas o grupo 2 precisa de uma entrada no mapa
        )
    )
);
?>




   Yaf_Route_Regex via Yaf_Router::addConfig


<?php

/**
 * Adiciona uma rota regex à pilha de rotas de Yaf_Router por meio de um array de configuração
 */
$config = array(
    "name" => array(
        "type"  => "regex",          // uma rota Yaf_Route_Regex
        "match" => "#(.*)#",         // corresponde a qualquer URI de requisição
        "route" => array(
            'controller' => "product", // roteia para o controlador product
            'action'     => "dummy",   // e para a ação dummy
        ),
        "map" => array(
            1 => "uri", // $request->getParam("uri") contém o URI correspondente
        ),
    ),
);

Yaf_Dispatcher::getInstance()->getRouter()->addConfig(
    new Yaf_Config_Simple($config)
);
?>
